void rmsnorm_accumulate_tile_16_128_1_ap_fixed_16_5___data_t_acc_t(
    data_t input[16][128],
    acc_t sumsq[16],
    int valid_rows,
    int valid_cols
)
{
    for (int r = 0; r < valid_rows; ++r) {
        acc_t sum = (acc_t)sumsq[r];
        for (int c = 0; c < valid_cols; ++c) {
            sum += (acc_t)input[r][c] * (acc_t)input[r][c];
        }
        sumsq[r] = sum;
    }
}

void rmsnorm_finalize_rows_16_4096_ap_fixed_16_5___acc_t_acc_t(
    acc_t sumsq[16],
    acc_t inv_rms[16],
    int valid_rows
)
{
    const acc_t eps = FB_EPS;
    for (int r = 0; r < valid_rows; ++r) {
        inv_rms[r] = fb_div(acc_t(1), fb_sqrt(fb_div(sumsq[r], acc_t(4096)) + eps));
    }
}

