void attention_score_tile_16_4_128_128_1_1_1_ap_fixed_16_5___data_t_data_t_acc_t(
    data_t q_tile[16][512],
    data_t k_tile[128][128],
    acc_t score[16][4][128],
    int valid_q,
    int valid_k,
    int q_index_base,
    int k_index_base
)
{
    const acc_t scale = acc_t(0.088388347648318433);
    for (int qt = 0; qt < valid_q; ++qt) {
        for (int qh = 0; qh < 4; ++qh) {
            int local_kv_head = qh / 4;
            for (int kt = 0; kt < valid_k; ++kt) {
                if ((k_index_base + kt) > (q_index_base + qt)) {
                    score[qt][qh][kt] = FB_MIN_SCORE;
                } else {
                    acc_t sum = (acc_t)0;
                    for (int d = 0; d < 128; ++d) {
                        sum += (acc_t)q_tile[qt][qh * 128 + d] * (acc_t)k_tile[kt][local_kv_head * 128 + d];
                    }
                    score[qt][qh][kt] = sum * scale;
                }
            }
        }
    }
}

void attention_rowmax_tile_16_4_128_1_ap_fixed_16_5___acc_t_acc_t(
    acc_t score[16][4][128],
    acc_t rowmax[16][4],
    int valid_q,
    int valid_k
)
{
    for (int qt = 0; qt < valid_q; ++qt) {
        for (int qh = 0; qh < 4; ++qh) {
            for (int kt = 0; kt < valid_k; ++kt) {
                if (score[qt][qh][kt] > rowmax[qt][qh]) {
                    rowmax[qt][qh] = score[qt][qh][kt];
                }
            }
        }
    }
}

void attention_softmax_context_tile_16_4_128_128_1_1_1_ap_fixed_16_5___acc_t_data_t_acc_t_acc_t_acc_t(
    acc_t score[16][4][128],
    data_t v_tile[128][128],
    acc_t rowmax[16][4],
    acc_t rowsum[16][4],
    acc_t ctx[16][512],
    int valid_q,
    int valid_k,
    int q_index_base,
    int k_index_base
)
{
    for (int qt = 0; qt < valid_q; ++qt) {
        for (int qh = 0; qh < 4; ++qh) {
            int local_kv_head = qh / 4;
            for (int kt = 0; kt < valid_k; ++kt) {
                if (k_index_base + kt > q_index_base + qt) continue;
                acc_t weight = fb_exp_negative(score[qt][qh][kt] - rowmax[qt][qh]);
                rowsum[qt][qh] += weight;
                for (int d = 0; d < 128; ++d) {
                    ctx[qt][qh * 128 + d] += weight * v_tile[kt][local_kv_head * 128 + d];
                }
            }
        }
    }
}

void attention_finalize_tile_16_4_128_1_1_ap_fixed_16_5___acc_t_acc_t(
    acc_t ctx[16][512],
    acc_t rowsum[16][4],
    int valid_q
)
{
    for (int qt = 0; qt < valid_q; ++qt) {
        for (int qh = 0; qh < 4; ++qh) {
            acc_t denom = rowsum[qt][qh];
            assert(denom > 0);
            for (int d = 0; d < 128; ++d) {
                ctx[qt][qh * 128 + d] = fb_div(ctx[qt][qh * 128 + d], denom);
            }
        }
    }
}

